#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<long long> nums(7);
    for (int i = 0; i < 7; i++) cin >> nums[i];
    sort(nums.begin(), nums.end());
    long long a = nums[0], b = nums[1];
    long long c = nums[6] - a - b;
    cout << a << ' ' << b << ' ' << c << '\n';
    return 0;
}

